import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
Q=[]
def add(n,i,p,a,e,proto,any_order=False,kind='text'):
 q=dict(id=f'russian-full-2027-{n:02d}-{i+1}',subject_code='russian',task_number=n,kind=kind,prompt='Авторский экзаменационный прототип, не официальный КИМ.\n\n'+p,options=[],answer=a,explanation=e,prototype=proto)
 if any_order:q['answer_order']='any'
 Q.append(q)
def variants(n,rows,instruction,proto,size=5):
 # Перекрывающиеся комплекты позволяют повторить правило в новом окружении.
 for i in range(10):
  selected=[rows[(i+j)%len(rows)] for j in range(size)]
  # Поворот сдвигает позиции верных ответов внутри полноценного комплекта.
  k=i%size;selected=selected[k:]+selected[:k]
  answer=''.join(str(j+1) for j,r in enumerate(selected) if r[1])
  assert answer,(n,i)
  add(n,i,instruction+'\n\n'+'\n'.join(f'{j+1}) {r[0]}' for j,r in enumerate(selected)),answer,'\n'.join(f'{j+1}) {r[2]}' for j,r in enumerate(selected)),proto,True)
